  const safeInput = input || {};
  const totalSupply = 1_000_000_000;
  const burnedTokens = safeInput.burnedTokens !== undefined
    ? Number(safeInput.burnedTokens)
    : (safeInput.totalSupply !== undefined
        ? totalSupply - Number(safeInput.totalSupply)
        : 10_118_369);
  const currentSupply = totalSupply - burnedTokens;
  const burnedPct = Number(((burnedTokens / totalSupply) * 100).toFixed(4));

  const hourlyBurnRate = safeInput.hourlyBurnRate !== undefined ? Number(safeInput.hourlyBurnRate) : 45_000; // tokens / hour
  const targetSupply = totalSupply * 0.02; // 2% target (98% destroyed)
  const remainingToBurn = Math.max(0, currentSupply - targetSupply);

  const hoursToHalving = hourlyBurnRate > 0 && currentSupply > 0 ? (currentSupply * 0.5) / hourlyBurnRate : 0;
  const daysToTargetSupply = hourlyBurnRate > 0 && remainingToBurn > 0 ? (remainingToBurn / (hourlyBurnRate * 24)) : 0;

  let burnBreakdown = safeInput.burnBreakdown;
  if (!burnBreakdown || typeof burnBreakdown !== 'object') {
    if (burnedTokens === 10_118_369) {
      burnBreakdown = {
        zeroCostInventoryBurns: 2_500_000,
        spillwayDamBurns: 4_100_000,
        symbioticMultiplierBurns: 1_850_000,
        flywheel5050Burns: 1_668_369
      };
    } else if (burnedTokens <= 0) {
      burnBreakdown = {
        zeroCostInventoryBurns: 0,
        spillwayDamBurns: 0,
        symbioticMultiplierBurns: 0,
        flywheel5050Burns: 0
      };
    } else {
      const z = Math.round(burnedTokens * (2_500_000 / 10_118_369));
      const s = Math.round(burnedTokens * (4_100_000 / 10_118_369));
      const m = Math.round(burnedTokens * (1_850_000 / 10_118_369));
      const f = burnedTokens - (z + s + m);
      burnBreakdown = {
        zeroCostInventoryBurns: z,
        spillwayDamBurns: s,
        symbioticMultiplierBurns: m,
        flywheel5050Burns: f
      };
    }
  }

  return {
    success: true,
    totalSupply,
    currentSupply,
    burnedTokens,
    burnedPct,
    hourlyBurnRate,
    burnBreakdown,
    projections: {
      hoursToSupplyHalving: Number(hoursToHalving.toFixed(1)),
      daysTo2PercentSupply: Number(daysToTargetSupply.toFixed(1))
    }
  };
};

